INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1rv411m7eu', 'course-bili-bv1rv411m7eu', '100001', '0', 'BILI-PRO-048', 'course-category-programming', 'instructor-bili-513670878', '黑马Redis快速入门，一套搞定Redis，常见数据结构及命令，包含Redis应用与优化、springdataRedis应用与优化', '22 讲完整课程 · 3 小时 47 分钟', 'Redis实战教程全套：BV1cr4y1671t 本课涵盖了Redis的各种数据结构和命令，Redis的各种常见Java客户端的应用和最佳实践。还有Redis在企业中的应用方案，例如共享session、缓存及缓存更新策略', '课程简介：Redis实战教程全套：BV1cr4y1671t 本课涵盖了Redis的各种数据结构和命令，Redis的各种常见Java客户端的应用和最佳实践。还有Redis在企业中的应用方案，例如共享session、缓存及缓存更新策略、分布式锁、消息队列、秒杀等等场景。另外还有Redis的主从、哨兵、集群等的搭建和原理，使用运维过程中的最佳实践方案。最后还会深入学习Redis底层原理、网络模型、通信模型、内存淘汰策略等内容 课程结构：共 3 章 22 讲，累计时长 3 小时 47 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立完整的编程知识框架，理解语言核心语法与运行机制","通过真实案例掌握调试、重构与工程化协作方法","独立完成课程配套项目，形成可写进简历的作品集","具备继续进阶框架、算法与系统设计的学习路径"]', '["零基础转行开发的初学者","需要系统补齐基础的在职开发者","希望掌握第二门语言的工程师"]', '["能熟练使用电脑与浏览器","具备基础的逻辑思维与英文文档阅读习惯"]', 'beginner', 'zh-CN', 'https://i1.hdslb.com/bfs/archive/8df440e7924da5bd7088aef7b325b099277fbbc0.png', '["编程开发","零基础","实战项目","黑马Redis快速入门","一套搞定Redis","常见数据结构及命令"]', 13630, 22, 44512, '4.3', 7028, 'BV1rV411M7eU', '49.00', '78.40', 'CNY', 0, 0, 'standard', NULL, '黑马Java', 0, 'tenant', 'published', '2023-07-06T03:41:18.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
